--- /dev/null
+++ b/src/db/site-store.js
@@ -0,0 +1,25 @@
+// A request-local view of location-owned records. Objects remain shared with
+// the underlying store, and appends go to the original collections.
+
+/** Returns a store view restricted to one site's locations and stock. */
+export function siteStore(store, site) {
+  const locations = new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+  const data = new Proxy(store.data, {
+    get(target, key) {
+      let predicate;
+      if (key === "locations") predicate = (l) => locations.has(l.id);
+      if (key === "batches" || key === "stocktakes" || key === "temperatures")
+        predicate = (row) => locations.has(row.location);
+      if (key === "movements") {
+        const batchIds = new Set(target.batches.filter((b) => locations.has(b.location)).map((b) => b.id));
+        predicate = (row) => batchIds.has(row.batchId);
+      }
+      if (!predicate) return target[key];
+      if (target[key] === undefined) return undefined;
+      const rows = target[key].filter(predicate);
+      rows.push = (...values) => target[key].push(...values);
+      return rows;
+    },
+  });
+  return { data, nextId: store.nextId.bind(store), save: store.save.bind(store) };
+}
